   elseif($type==='subjects') $item=['code'=>trim($_POST['code']??''),'name'=>trim($_POST['name']??''),'curriculum'=>trim($_POST['curriculum']??''),'teacher_id'=>(int)($_POST['teacher_id']??0)];
