   elseif($type==='results') $item=['student_id'=>(int)($_POST['student_id']??0),'subject_id'=>(int)($_POST['subject_id']??0),'term'=>trim($_POST['term']??'Term 1'),'assessment'=>trim($_POST['assessment']??''),'mark'=>(float)($_POST['mark']??0),'out_of'=>(float)($_POST['out_of']??100),'comment'=>trim($_POST['comment']??'')];
