   if($type==='users' && (!empty($item['password_hash']) && strlen($_POST['password']??'')<10)){flash('Password must be at least 10 characters.','error');redirect('school.php?section=users');}
   if($id){foreach($items as &$x)if((int)$x['id']===$id){$item['id']=$id;$item['created_at']=$x['created_at']??$now;$x=array_merge($x,$item);break;}unset($x);}
   else {$item['id']=next_id($items);$item['created_at']=$now;$items[]=$item;}
   write_json($type,$items); log_action('save',$type,(int)$item['id']); publish_data(); flash(ucfirst($type).' saved.'); redirect('school.php?section='.$section);
 }
