 if($act==='status'){ $type=$_POST['type']??'';$id=(int)$_POST['id'];$status=trim($_POST['status']??'');$items=read_json($type);foreach($items as &$x)if((int)$x['id']===$id)$x['status']=$status;unset($x);write_json($type,$items);log_action('status',$type,$id);flash('Status updated.');redirect('school.php?section='.$section);}
